/**
 * SSH session wrapper for deploy jobs.
 *
 * Connects via node-ssh (which sits on top of ssh2) using the Ed25519 PKCS#8
 * PEM private key generated by the edge function.
 *
 * Streams stdout/stderr line-by-line into a caller-provided log callback so
 * the deployer can flush to infra_byo_jobs.log in near real-time.
 */

import { NodeSSH, type Config as NodeSSHConfig } from 'node-ssh';
import ssh2Pkg from 'ssh2';
import type { ParsedKey } from 'ssh2';
import { createHash } from 'node:crypto';

const ssh2Utils = ssh2Pkg.utils;

export interface SshTarget {
  host: string;
  port: number;
  username: string;
  privateKeyPem: string;
}

export interface ExecResult {
  code: number | null;
  stdout: string;
  stderr: string;
}

export type LogFn = (line: string) => Promise<void> | void;

export interface ConnectedSshSession {
  ssh: NodeSSH;
  hostKeyFingerprint: string;        // OpenSSH SHA-256 fingerprint of remote host key
  exec: (command: string, opts?: { sudo?: boolean; log?: LogFn }) => Promise<ExecResult>;
  putContents: (remotePath: string, content: string) => Promise<void>;
  dispose: () => Promise<void>;
}

/**
 * Compute OpenSSH-style SHA-256 fingerprint from a parsed host key.
 */
function fingerprintFromParsedKey(key: ParsedKey): string {
  // ssh2's ParsedKey exposes the public-key blob via .getPublicSSH()
  const blob = (key as unknown as { getPublicSSH: () => Buffer }).getPublicSSH();
  const hash = createHash('sha256').update(blob).digest('base64').replace(/=+$/, '');
  return `SHA256:${hash}`;
}

export async function connectSsh(target: SshTarget, log?: LogFn): Promise<ConnectedSshSession> {
  const ssh = new NodeSSH();

  let observedFingerprint = '';

  const config: NodeSSHConfig = {
    host: target.host,
    port: target.port,
    username: target.username,
    privateKey: target.privateKeyPem,
    readyTimeout: 15_000,
    keepaliveInterval: 10_000,
    // Capture the host key fingerprint as it's negotiated.
    hostVerifier: (hostKey: string | Buffer) => {
      try {
        const parsed = ssh2Utils.parseKey(typeof hostKey === 'string' ? Buffer.from(hostKey) : hostKey);
        if (parsed instanceof Error) return true; // accept; we're recording, not pinning yet
        observedFingerprint = fingerprintFromParsedKey(parsed);
      } catch {
        // ignore — fall through and accept
      }
      return true;
    },
  };

  if (log) await log(`[ssh] connecting to ${target.username}@${target.host}:${target.port}`);
  await ssh.connect(config);
  if (log) await log(`[ssh] connected, host key ${observedFingerprint || 'unknown'}`);

  const exec = async (command: string, opts: { sudo?: boolean; log?: LogFn } = {}): Promise<ExecResult> => {
    const { sudo = false, log: lineLog } = opts;
    const finalCmd = sudo && target.username !== 'root' ? `sudo -n ${command}` : command;
    if (lineLog) await lineLog(`$ ${finalCmd}`);

    const out: string[] = [];
    const err: string[] = [];
    const result = await ssh.execCommand(finalCmd, {
      onStdout: (chunk: Buffer) => {
        const text = chunk.toString('utf8');
        out.push(text);
        if (lineLog) {
          for (const line of text.split('\n').filter(Boolean)) void lineLog(line);
        }
      },
      onStderr: (chunk: Buffer) => {
        const text = chunk.toString('utf8');
        err.push(text);
        if (lineLog) {
          for (const line of text.split('\n').filter(Boolean)) void lineLog(`[stderr] ${line}`);
        }
      },
    });
    return { code: result.code, stdout: out.join(''), stderr: err.join('') };
  };

  const putContents = async (remotePath: string, content: string): Promise<void> => {
    // node-ssh's putFile takes a local path; we use a tmp via heredoc to avoid disk I/O.
    const escaped = content.replace(/'/g, `'"'"'`);
    const result = await ssh.execCommand(`cat > '${remotePath}' <<'__EOF_ACA__'\n${content}\n__EOF_ACA__\n`);
    if (result.code !== 0) {
      // Fallback: try base64 + decode.
      const b64 = Buffer.from(content, 'utf8').toString('base64');
      const fallback = await ssh.execCommand(`echo '${b64}' | base64 -d > '${remotePath}'`);
      if (fallback.code !== 0) {
        throw new Error(`putContents failed for ${remotePath}: ${fallback.stderr}`);
      }
    }
    void escaped;
  };

  const dispose = async (): Promise<void> => {
    try { ssh.dispose(); } catch { /* ignore */ }
  };

  return { ssh, hostKeyFingerprint: observedFingerprint, exec, putContents, dispose };
}
